local _, ns = ...
if ns.LOCALE ~= "itIT" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/itIT.lua.
L["WN99_1_TITLE"] = "Condividere missioni"
L["WN99_1_TEXT"] = "La condivisione delle missioni dal registro delle missioni funziona di nuovo con il tuo gruppo."
L["WN99_2_TITLE"] = "Menu a tendina delle Opzioni"
L["WN99_2_TEXT"] = "I menu a tendina delle Opzioni del gioco non mostrano più un pulsante allungato al loro interno con un tema personalizzato con trama."
L["WN99_3_TITLE"] = "In combattimento"
L["WN99_3_TEXT"] = "In combattimento le barre delle azioni non saltano più quando si apre una finestra con un pulsante del micromenu nascosto, il libro delle professioni aperto dal libro degli incantesimi resta al suo posto senza un secondo riquadro vuoto, e ispezionare i talenti di un giocatore dal suo menu apre solo la nostra finestra, senza errori."
L["WN99_4_TITLE"] = "Chat"
L["WN99_4_TEXT"] = "La chat e le sue schede non spariscono più quando un altro addon ridimensiona la chat."
L["WN99_5_TITLE"] = "Menu a tendina e What's Training"
L["WN99_5_TEXT"] = "Con un tema personalizzato con trama, i menu a tendina delle nostre opzioni tornano a disegnarsi interi, e What's Training nel libro delle professioni ha il marmo nero del libro degli incantesimi senza linee sulla lista."
L["WN98_1_TITLE"] = "Icone delle borse sugli spazi vuoti"
L["WN98_1_TEXT"] = "In Una borsa, ogni spazio vuoto mostra ora un'icona sbiadita della borsa a cui appartiene, così gli spazi di una faretra si notano subito. Attivala nelle opzioni (/fcui): Una borsa, sotto Borse. Spazi vuoti semplici, subito sotto, li rende di nuovo tutti uguali."
L["WN98_2_TITLE"] = "Colori di classe nei campi di battaglia"
L["WN98_2_TEXT"] = "Le barre del nome dei giocatori nemici ora mostrano il colore della loro classe nei campi di battaglia e nelle spedizioni, dove il gioco nasconde la classe e apparivano rosse."
L["WN98_3_TITLE"] = "Le borse restano al loro posto"
L["WN98_3_TEXT"] = "Le borse spostate in modalità modifica ora restano dove le lasci. Quelle sistemate prima di questa versione restano dove sono."
L["WN98_4_TITLE"] = "Finestre in primo piano"
L["WN98_4_TEXT"] = "Una finestra trascinata sul registro delle missioni o sul libro degli incantesimi ora gli passa sopra, e le icone del libro degli incantesimi non si vedono più in trasparenza."
L["WN98_5_TITLE"] = "Schede della ricerca di gruppo"
L["WN98_5_TEXT"] = "La ricerca di gruppo e una finestra che un altro addon apre dalle sue schede laterali ora condividono lo stesso posto: cambiando scheda non salta più nulla, e trascinarne una sposta entrambe."
L["WN97_1_TITLE"] = "Nessuno spazio al livello massimo"
L["WN97_1_TEXT"] = "Al livello massimo, senza barra dell'esperienza o della reputazione, le barre sopra la barra principale ora poggiano sulla barra sottile dove c'era l'esperienza, come in Era."
L["WN97_2_TITLE"] = "Sfide dell'Eredità"
L["WN97_2_TEXT"] = "L'elenco delle Sfide annida le sue sezioni come la finestra del gioco, e la ricerca trova qualsiasi parola mostrata da una sfida, dalle sezioni ai passaggi."
L["WN97_3_TITLE"] = "Schede laterali di altri addon"
L["WN97_3_TEXT"] = "Le schede laterali che altri addon aggiungono alla ricerca gruppo, come quella di LFG Forever, ora hanno l'aspetto delle nostre e si allineano sotto di esse."
L["WN96_1_TITLE"] = "Tiri del bottino di Era"
L["WN96_1_TEXT"] = "/loot apre la finestra dei tiri del bottino di Era: ogni oggetto con vincitore e tiro, e + su un oggetto mostra tutti i tiri. Trascina la linguetta sotto per l'altezza, o il suo angolo per entrambi i sensi."
L["WN96_2_TITLE"] = "Apparire offline"
L["WN96_2_TEXT"] = "Il menu dello stato della finestra social classica ora permette di apparire offline, accanto a Disponibile, Assente e Occupato."
L["WN96_3_TITLE"] = "Social deselezionato"
L["WN96_3_TEXT"] = "Deselezionando Social nella pagina Tutte le finestre ora hai la finestra social del gioco, senza nessuna delle nostre linguette."
L["WN95_1_TITLE"] = "Una borsa per profilo"
L["WN95_1_TEXT"] = "I profili ora ricordano l'opzione Una borsa: i personaggi con profili diversi mantengono la propria modalità delle borse. Prima, una modifica su un personaggio valeva per tutti. Attivala nelle opzioni (/fcui) in ogni profilo che la vuole: Una borsa, in Borse."
L["WN95_2_TITLE"] = "Statistiche in combattimento"
L["WN95_2_TEXT"] = "Le statistiche della finestra del personaggio non sono più vuote alla prima apertura in combattimento, e attributi, salute, armatura, critico, celerità e schivata seguono i potenziamenti durante il combattimento."
L["WN94_1_TITLE"] = "Distribuzione del bottino"
L["WN94_1_TEXT"] = "La distribuzione del bottino al gruppo funziona di nuovo con la finestra del bottino classica: un clic su un oggetto mostra l'elenco dei giocatori, nello stile di Era sotto l'oggetto."
L["WN93_1_TITLE"] = "Stili delle targhette"
L["WN93_1_TEXT"] = "Classico è ora nella lista degli stili delle targhette del gioco (Opzioni, Targhette). Scegliere uno degli stili del gioco disattiva le nostre targhette perché si veda quello stile; Classico riporta le nostre."
L["WN93_2_TITLE"] = "Cronologia bottino"
L["WN93_2_TEXT"] = "La finestra della cronologia del bottino (/loot) ha la vecchia cornice con il tuo tema. Trascina il suo angolo per ridimensionarla in entrambi i sensi; clic destro sull'angolo per la sua dimensione originale."
L["WN93_3_TITLE"] = "Sfondo della barra delle posizioni"
L["WN93_3_TEXT"] = "Lo sfondo dietro le barre delle posizioni e del famiglio segue il tema delle barre delle azioni, come la grafica della barra stessa."
L["WN93_4_TITLE"] = "Quantità delle professioni"
L["WN93_4_TEXT"] = "Un clic nella casella della quantità della finestra delle professioni classica seleziona il numero, così scrivendo lo sostituisci, come in Era."
L["WN92_1_TITLE"] = "Barre delle posizioni e del famiglio"
L["WN92_1_TEXT"] = "Le barre delle posizioni, del famiglio e della possessione stanno dove le mette Era: sopra la barra principale sullo sfondo di Era, o appena sopra la barra 2 quando è attiva. Trascinane una in modalità modifica per posizionarla tu."
L["WN92_2_TITLE"] = "Barra dei totem"
L["WN92_2_TEXT"] = "La barra dei totem dello sciamano sta al posto della barra delle posizioni, sopra la barra principale, e ci resta dopo ogni caricamento."
L["WN92_3_TITLE"] = "Barre delle azioni"
L["WN92_3_TEXT"] = "Disattivando la barra 2 o la barra 3, l'altra resta dov'era."
L["WN92_4_TITLE"] = "Macro delle professioni"
L["WN92_4_TEXT"] = "Una macro può premere Crea nella finestra delle professioni classica, come una macro di incantamento rapido: /run ClassicUIForeverTradeSkill.CreateButton:Click()"
L["WN91_1_TITLE"] = "Tracciamento delle missioni"
L["WN91_1_TEXT"] = "Le missioni che hai tolto dal tracciamento ci tornano? È il tracciamento automatico delle missioni del gioco. Disattiva Tracciamento automatico delle missioni in Missioni (/fcui) e non torneranno."
L["WN91_2_TITLE"] = "Pannello incursione"
L["WN91_2_TEXT"] = "Il pannello del gruppo sul bordo sinistro dello schermo può restare nascosto finché non ci passi sopra con il mouse. Attivalo nelle opzioni (/fcui): Pannello incursione al passaggio del mouse, in Riquadri delle unità."
L["WN90_1_TITLE"] = "Colori delle missioni"
L["WN90_1_TEXT"] = "Tutte le missioni in giallo? È l'impostazione del gioco dei colori di difficoltà delle missioni, disattivata. Ora è anche nelle opzioni (/fcui): attiva Colori di difficoltà delle missioni in Missioni."
L["WN90_2_TITLE"] = "Scheda famiglio"
L["WN90_2_TEXT"] = "Mostra le statistiche che i famigli hanno davvero: salute, velocità, probabilità di critico, celerità, potere d'attacco, danni, difesa e armatura."
L["WN90_3_TITLE"] = "Borse"
L["WN90_3_TEXT"] = "Le borse trascinate sulla barra classica in modalità modifica restano lì dopo un nuovo accesso, ed è sparito un errore Lua che alcuni addon causavano aggiornando le borse."
L["WN90_4_TITLE"] = "Collezioni"
L["WN90_4_TEXT"] = "In Aspetti l'anteprima inquadra tutto il personaggio, e provare un altro aspetto nello stesso slot lascia la telecamera dove l'avevi messa."
L["WN90_5_TITLE"] = "Registro delle missioni"
L["WN90_5_TEXT"] = "Non rallenta più mentre un altro addon carica dati degli oggetti."
L["WN89_1_TITLE"] = "Niente più riquadro delle imprese"
L["WN89_1_TEXT"] = "Il riquadro del gioco che compare quando completi un'impresa (su Forever, una sfida dell'Eredità) o uno dei suoi passi è sparito, perché 1.x non ne aveva. Per riaverlo, attivalo nelle opzioni (/fcui): spunta Avviso di impresa sotto Altro."
L["WN89_2_TITLE"] = "Scheda Abilità"
L["WN89_2_TEXT"] = "Il suo riquadro inferiore non resta più visibile quando la finestra del personaggio si apre su un'altra scheda."
L["WN88_1_TITLE"] = "Famigli"
L["WN88_1_TEXT"] = "Evocare un altro famiglio non blocca più il gioco per un momento."
L["WN88_2_TITLE"] = "Registro delle missioni"
L["WN88_2_TEXT"] = "Abbandonare una missione riproduce il suono solo quando scegli Sì."
L["WN88_3_TITLE"] = "Professioni"
L["WN88_3_TEXT"] = "Il libro delle professioni conta l'equipaggiamento, come una canna da pesca, nel bonus di ogni abilità."
L["WN87_1_TITLE"] = "Descrizioni delle unità"
L["WN87_1_TEXT"] = "La riga che invita al clic destro per le opzioni del riquadro non compare più nelle descrizioni dei riquadri delle unità, come in Era. Per rivederla, disattiva Nascondi il suggerimento del clic destro nelle opzioni (/fcui), sotto Riquadri delle unità."
L["WN87_2_TITLE"] = "Borse"
L["WN87_2_TEXT"] = "Lo zaino mantiene la sua immagine classica quando cambiano le borse."
L["WN87_3_TITLE"] = "Finestra del personaggio"
L["WN87_3_TEXT"] = "Le righe della probabilità di colpire mostrano di nuovo la loro descrizione."
L["WN87_4_TITLE"] = "Mercanti"
L["WN87_4_TEXT"] = "I pulsanti di riparazione mostrano le icone di Era."
L["WN87_5_TITLE"] = "Barra dell'esperienza"
L["WN87_5_TEXT"] = "La barra dell'esperienza sta dove in Era ed è alta uguale."
L["WN86_1_TITLE"] = "Addon delle barre delle azioni"
L["WN86_1_TEXT"] = "Con un addon delle barre delle azioni che sostituisce le barre del gioco, le sue barre mantengono i loro pulsanti e il loro aspetto, skin di Masque comprese, ed Esci e Esci dal gioco del menu di gioco funzionano di nuovo."
L["WN86_2_TITLE"] = "Barra classica disattivata"
L["WN86_2_TEXT"] = "I pulsanti del famiglio e delle posture e il pulsante del personaggio tornano al loro aspetto."
L["WN85_1_TITLE"] = "Finestra delle opzioni del gioco"
L["WN85_1_TEXT"] = "La finestra delle opzioni del gioco non abbassa più la frequenza dei fotogrammi mentre è aperta."
L["WN85_2_TITLE"] = "Talenti"
L["WN85_2_TEXT"] = "Un talento bloccato finché il suo albero non ha abbastanza punti indica in rosso quanti ne servono, come in Era."
L["WN85_3_TITLE"] = "Barra dell'esperienza"
L["WN85_3_TEXT"] = "Le linee dei segmenti del gioco non compaiono più sulla barra dell'esperienza dopo un accesso in combattimento."
L["WN85_4_TITLE"] = "Professioni"
L["WN85_4_TEXT"] = "Il libro delle professioni tiene insieme gli incantesimi di ogni professione quando viene aperto in combattimento, e con TradeSkillMaster la finestra delle professioni non salta più a destra alla fine di un combattimento."
L["WN84_1_TITLE"] = "Finestre di mercante e istruttore"
L["WN84_1_TEXT"] = "Le finestre di mercanti e istruttori ora si possono spostare e ridimensionare. Fai clic sul lucchetto accanto al pulsante di chiusura, poi trascina la finestra o il suo angolo. Condividono posizione e dimensione con le finestre delle missioni e di dialogo, e in Finestre di ClassicUI Forever le finestre che condividono una posizione sono una sola riga e un solo riquadro."
L["WN84_2_TITLE"] = "Tracciamento e impostazioni delle missioni della mappa"
L["WN84_2_TEXT"] = "I titoli delle missioni nel tracciamento classico, nel registro delle missioni e negli elenchi di missioni della mappa seguono l'impostazione della mappa Quest Difficulty Color (semplici quando è disattivata), e questa impostazione e Show Quest Levels si applicano subito, senza ricaricare."
L["WN84_3_TITLE"] = "Correzioni"
L["WN84_3_TEXT"] = "Il titolo di una missione nel tracciamento classico mantiene il suo colore quando il mouse lo lascia, le barre di scorrimento della mappa classica combinata stanno al loro posto quando la mappa è in finestra, il tasto della mappa chiude quella mappa su tutti i personaggi, e il pulsante della minimappa resta nella borsa di MinimapButtonBag Reborn."
L["WN84_4_TITLE"] = "Scheda Abilità"
L["WN84_4_TEXT"] = "Un'abilità che aumenta in combattimento non causa più un errore mentre la scheda Abilità mostra un'abilità con le armi."
L["WN83_1_TITLE"] = "Abilità e casa d'aste"
L["WN83_1_TEXT"] = "La scheda Abilità non causa più un errore per un personaggio con un bonus a Difesa, e il pulsante dell'offerta della casa d'aste non copre più la fine della casella del rame."
L["WN83_2_TITLE"] = "Pannello di incursione e controller"
L["WN83_2_TEXT"] = "La linguetta chiusa del pannello di incursione resta al bordo dello schermo quando entri in un gruppo in combattimento, e le opzioni del controller mostrano le icone Visualizza e Menu del tuo controller."
L["WN82_1_TITLE"] = "Condividi missione con la mappa a schermo intero"
L["WN82_1_TEXT"] = "Condividere una missione dal registro delle missioni non lascia più aperta la mappa del mondo quando usi la mappa a schermo intero."
L["WN82_2_TITLE"] = "Condividi missione"
L["WN82_2_TEXT"] = "Condividi missione nel registro delle missioni condivide la missione, invece di dire di condividerla dalla mappa del mondo."
L["WN81_1_TITLE"] = "Costo di creazione e profitto"
L["WN81_1_TEXT"] = "Con Auctionator, la finestra classica delle professioni mostra sopra i reagenti quanto costa creare una ricetta e il suo profitto, e un pulsante Cerca per i reagenti mentre la casa d'aste è aperta."
L["WN81_2_TITLE"] = "Colori di classe per amici o nemici"
L["WN81_2_TEXT"] = "Giocatori amici e Giocatori nemici sono caselle separate sotto i colori di classe delle targhette, il riquadro del nome con colore di classe e la salute con colore di classe: possono valere per una sola parte. Le opzioni dei colori di classe sono disattivate per impostazione predefinita: attivale nelle opzioni (/fcui)."
L["WN81_3_TITLE"] = "Corsa automatica con il controller"
L["WN81_3_TEXT"] = "Sul layout classico, la corsa automatica è per impostazione predefinita sulla pressione della levetta sinistra, e un tasto scelto per corsa automatica o chat funziona anche su una levetta con cui il cursore fa clic."
L["WN81_4_TITLE"] = "Correzioni"
L["WN81_4_TEXT"] = "L'elenco di What's Training nella finestra delle professioni a doppio riquadro poggia su un solo sfondo, e le barre di salute e focus del riquadro del famiglio riempiono i loro spazi."
L["WN80_1_TITLE"] = "Controller sul layout classico (in lavorazione)"
L["WN80_1_TEXT"] = "Gioca con le barre classiche usando un controller mentre l'interfaccia gamepad del gioco è disattivata: la croce direzionale e i tasti frontali attivano la barra delle azioni 1, o le altre barre con un grilletto premuto. Disattivato per impostazione predefinita; la prima volta che usi un controller una finestra te lo chiede, ed è nelle opzioni (/fcui), sotto Gamepad. Ancora in lavorazione: borse, mappa e menu richiedono per ora il cursore del gioco."
L["WN80_2_TITLE"] = "Pannello dell'incursione in combattimento"
L["WN80_2_TEXT"] = "Il pannello di incursione e gruppo mantiene le sue righe al loro posto quando il gruppo cambia durante un combattimento, e la sua linguetta non sparisce più quando chiudi il pannello in combattimento."
L["WN80_3_TITLE"] = "Addestramento del famiglio"
L["WN80_3_TEXT"] = "La finestra dell'istruttore non conserva più un vecchio elenco: le abilità che il tuo famiglio conosce già non restano indicate come apprendibili."
L["WN79_1_TITLE"] = "Pannello di incursione in combattimento"
L["WN79_1_TEXT"] = "Il pannello di incursione e gruppo non causa più un errore quando il tuo gruppo cambia durante un combattimento, per esempio quando un membro sale di livello. Si aggiorna alla fine del combattimento."
L["WN78_1_TITLE"] = "Pannello incursione classico"
L["WN78_1_TEXT"] = "Il pannello di incursione e gruppo sul bordo sinistro dello schermo ha l'aspetto e l'ordine classici, e tutti i comandi del gioco ci sono ancora. Il suo pulsante dei segnalini a terra fa segnare il terreno alle icone del bersaglio."
L["WN78_2_TITLE"] = "Bordo del pannello incursione"
L["WN78_2_TEXT"] = "Da chiuso, il pannello mostra solo la linguetta con la freccia. Bordo del pannello incursione da chiuso lascia la sua cornice sul bordo dello schermo, come in Era. Disattivato in modo predefinito; attivalo nelle opzioni (/fcui), sotto Riquadri delle unità."
L["WN78_3_TITLE"] = "Piccole correzioni"
L["WN78_3_TEXT"] = "La finestra del bottino si apre subito e non salta più quando clicchi un oggetto con le borse piene. I pulsanti della scheda di gilda e della finestra delle comunità non restano più cliccabili dopo la chiusura della loro finestra in combattimento."
L["WN77_1_TITLE"] = "Ricerca dall'istruttore"
L["WN77_1_TEXT"] = "La finestra di un istruttore ha una casella di ricerca accanto al filtro. Mostra solo gli incantesimi e le ricette il cui nome contiene le parole. Casella di ricerca, sotto Finestra dell'istruttore nelle opzioni (/fcui), la disattiva."
L["WN77_2_TITLE"] = "What's Training in una finestra propria"
L["WN77_2_TEXT"] = "La scheda di addestramento del libro degli incantesimi può aprire la finestra di What's Training invece di una pagina del libro; la finestra si chiude con il libro. Disattivato di default; attivalo nelle opzioni (/fcui), sotto Libro degli incantesimi."
L["WN77_3_TITLE"] = "Nomi di gilda nel colore della classe"
L["WN77_3_TEXT"] = "I nomi nell'elenco della gilda possono apparire nel colore della loro classe. Disattivato di default; attivalo nelle opzioni (/fcui), sotto Elenco della gilda."
L["WN77_4_TITLE"] = "Banca classica"
L["WN77_4_TEXT"] = "La banca ha le piastre degli slot e i rivetti classici, con la spaziatura classica, in una finestra più bassa."
L["WN77_5_TITLE"] = "Caselle di ricerca"
L["WN77_5_TEXT"] = "Le caselle di ricerca del registro delle missioni e delle professioni hanno l'aspetto classico dei campi di testo."
L["WN77_6_TITLE"] = "Avvisi sopra la chat"
L["WN77_6_TEXT"] = "Le notifiche degli amici e l'avviso di aggiornamento del mondo stanno sopra le schede della chat. Su una chat più alta coprivano il testo e le schede."
L["WN77_7_TITLE"] = "Piccole correzioni"
L["WN77_7_TEXT"] = "Forever Quest Tint copre tutta la pagina della missione sulla mappa, non una striscia sotto il titolo. Chiudere una banca o un mercante non sposta più per un attimo le borse aperte, e /fstack non elenca più i riquadri ausiliari nascosti dell'addon."
L["WN76_1_TITLE"] = "Ricerca nel registro delle missioni"
L["WN76_1_TEXT"] = "Il registro delle missioni a riquadro doppio ha una casella di ricerca nell'intestazione. Elenca le missioni il cui nome o la cui zona contiene le parole."
L["WN76_2_TITLE"] = "Ordina per difficoltà"
L["WN76_2_TEXT"] = "Tutte le ricette di una professione in un unico elenco, prima arancione, poi giallo, verde e grigio. Attivalo nel menu Filtro della finestra di una professione o nelle opzioni (/fcui), in Professioni."
L["WN76_3_TITLE"] = "Pulsanti di chiusura classici"
L["WN76_3_TEXT"] = "La banca di gilda e la mappa del maestro di volo hanno la X classica."
L["WN75_1_TITLE"] = "Tooltip di un link di oggetto"
L["WN75_1_TEXT"] = "La X del tooltip di un link di oggetto è quella classica, al suo posto classico."
L["WN75_2_TITLE"] = "Abilità del famiglio sul cursore"
L["WN75_2_TEXT"] = "Dopo un cambio di famiglio, un'abilità del famiglio di cui il gioco non conserva la copia viene piazzata una volta, non di continuo. Con alcuni famigli questo metteva icone sul cursore e rallentava il gioco."
L["WN74_1_TITLE"] = "Pagina di addestramento del libro degli incantesimi"
L["WN74_1_TEXT"] = "La pagina di addestramento del libro degli incantesimi funziona con What's Training 11.3. Con quella versione la scheda apriva la finestra propria di What's Training invece dell'elenco nel libro."
L["WN74_2_TITLE"] = "Condividi missione dal registro"
L["WN74_2_TEXT"] = "Condividi missione nel registro delle missioni condivide anche le missioni fuori dalla zona in cui ti trovi, spedizioni comprese, e lascia la mappa del mondo chiusa dopo."
L["WN73_1_TITLE"] = "Addestramento nella finestra di una professione"
L["WN73_1_TEXT"] = "Con What's Training installato, la finestra di una professione ha due schede laterali: quella in basso elenca ciò che il suo addestratore può insegnarti, quella in alto torna alla professione. Le schede di addestramento portano le icone di What's Training, anche nel libro degli incantesimi."
L["WN73_2_TITLE"] = "Bottino in combattimento"
L["WN73_2_TEXT"] = "Saccheggiare un cadavere in combattimento apre la finestra del bottino. Dal secondo saccheggio di una sessione il gioco la rifiutava con il messaggio che un'azione dell'interfaccia è fallita a causa di un addon."
L["WN73_3_TITLE"] = "Libro degli incantesimi"
L["WN73_3_TEXT"] = "Il pulsante del micromenu e il tasto chiudono il libro dalla pagina di What's Training, e un libro chiuso lì si riapre. In combattimento il libro si apre all'inizio della fila di finestre; si apriva molto a destra quando la mappa era aperta all'inizio del combattimento."
L["WN73_4_TITLE"] = "Dimensione delle targhette per personaggio"
L["WN73_4_TEXT"] = "Stessa dimensione vicino e lontano applica la scelta di ogni personaggio all'accesso. Aveva effetto solo dopo aver cambiato la casella su quel personaggio. Attivala nelle opzioni (/fcui), sotto Targhette."
L["WN72_1_TITLE"] = "Camerino"
L["WN72_1_TEXT"] = "Il camerino si apre alla dimensione di 1.x. Per il camerino più grande dei client successivi, attiva Camerino grande nelle opzioni (/fcui), sotto Tutte le finestre; le nostre finestre gli lasciano spazio accanto per i suoi pannelli laterali."
L["WN72_2_TITLE"] = "Dissolvenza del micromenu"
L["WN72_2_TEXT"] = "Il micromenu può attenuarsi come le barre delle azioni: imposta Opacità attenuata o Mostra solo al passaggio del mouse nella sua finestra della modalità modifica, e collegalo alle barre attenuate."
L["WN72_3_TITLE"] = "Finestra della gilda"
L["WN72_3_TEXT"] = "Aggiungi membro, Informazioni gilda e il menu del clic destro su un membro passano dai pulsanti e dal menu del gioco stesso, così invitare, modificare le informazioni, rimuovere, promuovere e retrocedere funzionano."
L["WN72_4_TITLE"] = "Scheda laterale Chi"
L["WN72_4_TEXT"] = "La scheda laterale Chi della ricerca gruppi è nascosta per tutti. Disattiva Nascondi scheda laterale Chi nelle opzioni (/fcui), sotto Sociale, per riaverla."
L["WN72_5_TITLE"] = "Dimensione delle targhette"
L["WN72_5_TEXT"] = "Stessa dimensione vicino e lontano tiene le targhette a una sola dimensione come in Classic Era, ora tramite le impostazioni del gioco e salvata per personaggio, fuori dai profili. Attivala nelle opzioni (/fcui), sotto Targhette."
L["WN72_6_TITLE"] = "Correzioni"
L["WN72_6_TEXT"] = "Un nome lungo di gilda termina con i puntini prima della colonna della zona, la finestra dell'addestratore scorre una descrizione lunga, Ctrl+clic su una ricompensa di missione apre il camerino, i pulsanti della barra dei totem hanno l'aspetto classico, il numero del gruppo di una missione resta anche senza i livelli delle missioni, e gli elenchi di What's Training stanno su una pagina del libro degli incantesimi con una scheda Professioni accanto."
L["WN71_1_TITLE"] = "La barra dei totem resta al suo posto"
L["WN71_1_TEXT"] = "Una barra agganciata a una barra delle azioni in modalità modifica, come la barra dei totem dello sciamano, mantiene il suo posto alla chiusura della modalità modifica e dopo un ricaricamento."
L["WN71_2_TITLE"] = "Vassoi dei pulsanti della minimappa"
L["WN71_2_TEXT"] = "Un vassoio dei pulsanti della minimappa di un altro addon si può spostare di nuovo con ClassicUI Forever attivo."
L["WN71_3_TITLE"] = "Percentuale di minaccia"
L["WN71_3_TEXT"] = "La percentuale di minaccia su bersaglio e focus si ferma al 999%, come in Classic Era."
L["WN70_1_TITLE"] = "Sbiadimento collegato"
L["WN70_1_TEXT"] = "Le barre delle azioni sbiadite possono tornare insieme: spunta Collegata alle altre barre sbiadite sulle barre sbiadite, in modalità modifica, e il mouse su una qualsiasi le mostra tutte (#255)."
L["WN70_2_TITLE"] = "Bagliore dell'incantamento"
L["WN70_2_TEXT"] = "Il bagliore dorato del gioco dopo una cote, un olio o un incantamento è disattivato, perché Classic Era non lo aveva. Per riaverlo, attivalo nelle opzioni (/fcui): Bagliore dorato all'incantamento sotto Scheda del personaggio. Ora segue il bordo della finestra (#262)."
L["WN70_4_TITLE"] = "Scheda dei titoli"
L["WN70_4_TEXT"] = "Il pannello laterale della finestra del personaggio ha di nuovo la scheda Titoli (#261). Le icone dei talenti riempiono i loro riquadri come in Classic Era (#260)."
L["WN70_3_TITLE"] = "Finestra del bottino col controller"
L["WN70_3_TEXT"] = "Col controller, la croce direzionale scorre gli oggetti della finestra del bottino (#264)."
L["WN69_1_TITLE"] = "Le nostre finestre con il controller"
L["WN69_1_TEXT"] = "Con l'interfaccia controller attiva, il libro degli incantesimi classico, i talenti, il registro missioni, le collezioni, la finestra Legacy e la borsa unica funzionano con il controller: la croce direzionale sposta, A seleziona, B chiude, e i tasti da premere sono mostrati sotto la finestra. Il libro degli incantesimi e i talenti si aprono di nuovo come finestre proprie. Nel registro missioni l'elenco scorre mentre ti muovi, e Y apre la mappa."
L["WN69_2_TITLE"] = "Assegna incantesimi dal libro degli incantesimi"
L["WN69_2_TEXT"] = "Con il controller premi X su un incantesimo del libro degli incantesimi classico, poi il tasto per esso; tieni premuto LT o RT per i gruppi laterali, come nel libro del gioco. Y apre l'editor delle barre delle azioni del gioco."
L["WN69_3_TITLE"] = "Schede professione nascoste"
L["WN69_3_TEXT"] = "Le schede accanto alla finestra delle professioni sono nascoste, perché Classic Era non le aveva. Per riaverle, attivale nelle opzioni (/fcui): scegli Schede professione: al passaggio o sempre visibili sotto Libro delle professioni. L'elenco delle ricette da imparare di What's Training si apre da una scheda accanto al libro (#260)."
L["WN69_4_TITLE"] = "Modifiche minori"
L["WN69_4_TEXT"] = "La finestra della chat resta al suo posto quando un altro addon la ridimensiona dal bordo superiore (#247). Con il controller, le schede Libro degli incantesimi e Collezioni della finestra delle professioni girano la pagina sul posto, e il contorno della finestra del personaggio aderisce alla sua cornice."
L["WN68_1_TITLE"] = "Schede della doppia specializzazione sulla finestra dei talenti"
L["WN68_1_TEXT"] = "Le schede delle due specializzazioni scendono lungo il bordo della finestra dei talenti, come in Classic. Cliccane una per vedere quella specializzazione."
L["WN68_2_TITLE"] = "Il testo della mappa del mondo a grandezza di gioco"
L["WN68_2_TEXT"] = "Nello stile Classic dell'intestazione, l'intestazione, il pannello delle missioni e le Opzioni mappa erano al 70% della grandezza del testo di gioco in finestra. Ora sono a grandezza di gioco, il pannello delle missioni ha la sua larghezza piena, e le etichette Continente e Zona stanno accanto ai loro menu a discesa."
L["WN68_3_TITLE"] = "Missioni su pergamena nel pannello della mappa"
L["WN68_3_TEXT"] = "Il pannello delle missioni della mappa elenca le missioni sulla pergamena del gioco. Per la pietra scura, togli la spunta a Elenco sulla pergamena del gioco sotto Mappa del mondo."
L["WN68_4_TITLE"] = "Pulsanti degli addon lasciati sull'anello"
L["WN68_4_TEXT"] = "Con Raccogli i pulsanti degli addon attivo, Lascia sull'anello elenca ogni pulsante degli addon; spunta quelli che restano sull'anello mentre gli altri vanno nella borsa. Raccogli i pulsanti degli addon è disattivato per impostazione predefinita; attivalo nelle opzioni (/fcui), sotto Minimappa."
L["WN68_5_TITLE"] = "Niente più riquadro Nuova ricetta appresa"
L["WN68_5_TEXT"] = "Il riquadro del gioco che compare quando una professione ti insegna qualcosa è sparito, perché 1.x non ne aveva. Per riaverlo, attivalo nelle opzioni (/fcui): spunta Avviso di abilità sotto Altro."
L["WN68_6_TITLE"] = "Modifiche minori"
L["WN68_6_TEXT"] = "Un talento sotto il suo grado massimo è verde, che tu abbia punti da spendere o no, come in Classic Era. Le liste della finestra sociale contano le righe intere (#232), e la riga Numeri dei danni è sparita, perché rispecchiava solo l'impostazione del gioco stesso."
L["WN67_1_TITLE"] = "I pezzi della minimappa restano su di essa"
L["WN67_1_TEXT"] = "Ogni pezzo della minimappa in ClassicUI Forever Windows ha una casella Resta sulla minimappa. Spuntata, il pezzo tiene il suo posto sulla minimappa. Togli la spunta per trascinarlo ovunque."
L["WN67_2_TITLE"] = "La finestra Opzioni segue il tema"
L["WN67_2_TEXT"] = "Il suo bordo e i pezzi di Classic Era vestono il look scuro, bronzo o personalizzato, e nel look classico non resta bronzo sui suoi bordi."
L["WN67_3_TITLE"] = "Gli slot e l'intestazione della borsa unica"
L["WN67_3_TEXT"] = "Gli slot vuoti non mostrano l'icona della borsa, la ricerca arriva al pulsante Riordina e la fascia d'intestazione è intera."
L["WN67_4_TITLE"] = "La mappa del mondo in combattimento"
L["WN67_4_TEXT"] = "Aperta in combattimento, la mappa è dimensionata dal solo addon, così un altro addon di mappe non può più causare un errore di azione bloccata."
L["WN66_1_TITLE"] = "I tooltip tornano scuri come in Classic Era"
L["WN66_1_TEXT"] = "Ogni tooltip ha lo sfondo scuro di Era in ogni stile. Lo sfondo più chiaro e bluastro del gioco traspariva dal secondo tooltip in poi, con uno spazio vuoto lungo il bordo."
L["WN66_2_TITLE"] = "La minimappa si sposta di nuovo in modalità Modifica"
L["WN66_2_TEXT"] = "Trascinata in modalità Modifica, la minimappa resta visibile e la nuova posizione viene salvata."
L["WN66_3_TITLE"] = "La mappa del mondo mantiene le dimensioni in combattimento"
L["WN66_3_TEXT"] = "Aperta in combattimento, la mappa ha le stesse dimensioni che ha fuori, con o senza il registro delle missioni."
L["WN65_1_TITLE"] = "Sposta tutte le finestre insieme"
L["WN65_1_TEXT"] = "ClassicUI Forever Windows ha un riquadro Fila di finestre: trascinalo e tutte le finestre che si aprono una accanto all'altra si spostano lì insieme."
L["WN65_2_TITLE"] = "L'addestramento del famiglio torna in punti addestramento"
L["WN65_2_TEXT"] = "La finestra dell'addestratore mostra i punti addestramento del tuo famiglio e quanti punti costa ogni abilità, e Addestra si basa su quelli, come in Classic Era."

L["WN64_1_TITLE"] = "Sbiadisci le barre delle azioni"
L["WN64_1_TEXT"] = "Scegli una barra in modalità Modifica: sotto le impostazioni del gioco per essa, imposta fin dove sbiadisce o spunta Mostra solo al passaggio del mouse. Torna piena con il mouse sopra o mentre trascini un incantesimo su di essa."
L["WN64_2_TITLE"] = "Errore delle targhette corretto"
L["WN64_2_TEXT"] = "Con le targhette del gioco e le aure di un altro addon sopra, le nuove targhette non causano più un errore Lua."
L["WN64_3_TITLE"] = "Spazi vuoti dopo il libro degli incantesimi"
L["WN64_3_TEXT"] = "Con Mostra sempre i pulsanti disattivato, gli spazi vuoti delle barre tornano visibili per un incantesimo o un oggetto preso dopo aver chiuso il libro degli incantesimi."
L["WN64_4_TITLE"] = "Correzioni a ClassicUI Forever Windows"
L["WN64_4_TEXT"] = "La sua casella in modalità Modifica risponde di nuovo ai clic, e la dimensione della mappa del mondo lì cambia in modo uniforme da quella con cui si apre."

L["WN63_1_TITLE"] = "Descrizioni del bottino accanto all'oggetto"
L["WN63_1_TEXT"] = "Nella finestra del bottino la descrizione di un oggetto si apre accanto alla sua icona, come in Classic Era, e non oltre il bordo destro della finestra."

L["WN62_1_TITLE"] = "Distanzia le barre delle azioni"
L["WN62_1_TEXT"] = "La spaziatura delle icone della modalità Modifica ora distanzia i pulsanti di ogni barra delle azioni. Sulla barra delle azioni 1 la fascia di pietra si allarga con essa e ogni pulsante resta nel suo alloggiamento."
L["WN62_2_TITLE"] = "Scarta i regali nelle Collezioni"
L["WN62_2_TEXT"] = "Cavalcature, mascotte e giocattoli incartati si possono scartare nella finestra classica delle Collezioni: scegline uno e fai clic su Scarta, oppure fai clic su un giocattolo incartato."
L["WN62_3_TITLE"] = "Descrizioni come in Classic Era"
L["WN62_3_TEXT"] = "Le descrizioni del look classico hanno lo sfondo di Classic Era: lo stesso colore scuro e la stessa trasparenza, dove prima erano più blu e più coprenti."

L["WN61_1_TITLE"] = "Domande sulla dimensione più chiare"
L["WN61_1_TEXT"] = "Le domande e le caselle sulla dimensione dell'interfaccia indicano la scala dell'interfaccia del gioco e la percentuale che impostano, in meno parole."
L["WN60_1_TITLE"] = "Riquadri dei boss classici"
L["WN60_1_TEXT"] = "I riquadri dei boss negli scontri di spedizioni e incursioni indossano il vecchio riquadro col drago, con il livello nel suo anello rotondo e la barra di lancio accanto o sotto il riquadro. Per riavere quelli del gioco, togli la spunta a Boss nella lista Riquadri delle opzioni (/fcui), sotto Riquadri delle unità."
L["WN60_2_TITLE"] = "Nascondi bordi di qualità"
L["WN60_2_TEXT"] = "Gli oggetti che indossi nella scheda del personaggio possono apparire senza il bordo colorato della loro qualità. È disattivato in modo predefinito; attivalo nelle opzioni (/fcui), sotto Scheda del personaggio."
L["WN59_1_TITLE"] = "Meno lavoro per il gioco"
L["WN59_1_TEXT"] = "Le targhette lavorano molto meno quando cambi bersaglio, lanci incantesimi, ottieni o perdi aure, o sei tra altri giocatori. Anche i riquadri del bersaglio e del focus e l'Elenco Chi fanno meno lavoro in background."
L["WN58_1_TITLE"] = "Segnalini dei villaggi di Era"
L["WN58_1_TEXT"] = "Revantusk Village e Cenarion Hold compaiono sulle mappe dei continenti solo dopo che ne hai esplorato la zona, come in Classic Era."
L["WN57_1_TITLE"] = "Mostra le borse con un clic"
L["WN57_1_TEXT"] = "Con Barra delle borse: solo lo zaino, un Ctrl-clic sullo zaino mostra le altre borse o le ripiega di nuovo; la freccia accanto non c'è più. Mostra le borse con sceglie un altro clic. Per attivarlo, scegli Barra delle borse: solo lo zaino nelle opzioni (/fcui), in Borse."
L["WN57_2_TITLE"] = "Nascondi la grafica del portachiavi"
L["WN57_2_TEXT"] = "Nascondi la grafica del portachiavi ora libera anche il posto del portachiavi sulla barra classica e sostituisce Nascondi anche la grafica del portachiavi, mantenendo la tua scelta. È disattivato in modo predefinito; attivalo nelle opzioni (/fcui), in Borse."
L["WN57_3_TITLE"] = "Borse senza Barra classica"
L["WN57_3_TEXT"] = "Con Barra classica disattivata, le scelte che la barra delle borse del gioco non può seguire sono in grigio, e il loro suggerimento dice perché."
L["WN56_1_TITLE"] = "Tema personalizzato più veloce"
L["WN56_1_TEXT"] = "Cambiare aspetto o una parte di Con tema non blocca più il gioco, e una parte deselezionata riprende i colori del gioco. Tema personalizzato è disattivato in modo predefinito; attivalo nelle opzioni (/fcui), in Aspetto."
L["WN55_1_TITLE"] = "Texture delle barre"
L["WN55_1_TEXT"] = "Una scelta di Texture delle barre in Riquadri delle unità per le barre di salute e mana: Classica, ora più liscia, Riquadri incursione, Tinta unita o Barra delle abilità."
L["WN55_2_TITLE"] = "Pulsante del negozio"
L["WN55_2_TEXT"] = "Il pulsante del negozio può stare nel micromenu della 1.x con una cornice sua. È nascosto per impostazione predefinita: per mostrarlo, togli la spunta a Negozio sotto Nascondi micropulsanti, nella pagina Barre delle azioni delle opzioni (/fcui)."
L["WN55_3_TITLE"] = "Pulsante del libro degli incantesimi"
L["WN55_3_TEXT"] = "Il pulsante del libro degli incantesimi nel micromenu resta premuto mentre il libro mostra i tuoi incantesimi."
L["WN55_4_TITLE"] = "Correzioni"
L["WN55_4_TEXT"] = "Il suggerimento del pulsante sociale dice Social, e un titolo di finestra lungo mantiene le estremità della sua targa."
L["WN54_1_TITLE"] = "Opzioni più fluide"
L["WN54_1_TEXT"] = "Cambiare un'opzione non scatta più: si ridispongono solo le parti dell'interfaccia toccate da quell'opzione."
L["WN54_2_TITLE"] = "Micromenu"
L["WN54_2_TEXT"] = "I micropulsanti che nascondi restano nascosti, un pulsante rimasto da solo sulla fila si mette in fondo, e la fila sta al centro della barra senza buchi nel suo fondo."
L["WN54_3_TITLE"] = "Minimappa nelle istanze"
L["WN54_3_TEXT"] = "Con Ruota minimappa attivo, le istanze non mostrano più un secondo grande anello attorno alla minimappa."
L["WN54_4_TITLE"] = "Pulsante degli alloggi"
L["WN54_4_TEXT"] = "Il pulsante degli alloggi nel micromenu ha una cornice 1.x come gli altri."
L["WN54_5_TITLE"] = "Correzioni"
L["WN54_5_TEXT"] = "Dopo un ricaricamento in combattimento, la cornice della barra dell'esperienza del gioco non compare più sopra quella 1.x, e una dimensione di finestra salvata in modalità modifica non può più spingere una finestra fuori dallo schermo, come una grande mappa del mondo."
L["WN53_1_TITLE"] = "Parti del tema più fini"
L["WN53_1_TEXT"] = "In Tema personalizzato, l'elenco Con tema si divide in parti più fini, come le barre di lancio, le targhette, il micromenu e i menu, così puoi lasciare ognuna con l'aspetto classico. Tema personalizzato è disattivato in modo predefinito; attivalo nelle opzioni (/fcui), in Aspetto."
L["WN53_2_TITLE"] = "Barre delle azioni a destra"
L["WN53_2_TEXT"] = "Con Barra classica disattivata e la minimappa ingrandita in modalità modifica, le barre delle azioni 4 e 5 a destra non si riducono più a circa due terzi; si riducono solo quanto richiede lo spazio sotto la minimappa."
L["WN53_3_TITLE"] = "Colore personalizzato"
L["WN53_3_TEXT"] = "Un clic fuori dal selettore di colore mantiene il colore scelto; Annulla o Esc lo annullano ancora."
L["WN53_4_TITLE"] = "Correzioni del tema"
L["WN53_4_TEXT"] = "Quando il tema colora le finestre del gioco, non lampeggiano più nei loro colori all'apertura, e i pulsanti rossi del menu di gioco mostrano bene le estremità. I riquadri degli altri addon mantengono il loro aspetto; per colorarli, attiva Altri addon nell'elenco Con tema, nelle opzioni (/fcui), in Aspetto."
L["WN52_1_TITLE"] = "Distintivo d'onore"
L["WN52_1_TEXT"] = "I riquadri del giocatore, del bersaglio e del focus possono mostrare il distintivo del livello d'onore del gioco al posto dell'emblema di fazione della 1.x. Disattivato in modo predefinito; attivalo nelle opzioni (/fcui), in Riquadri delle unità."
L["WN52_2_TITLE"] = "Schede della chat al passaggio"
L["WN52_2_TEXT"] = "Con le schede della chat al passaggio, compaiono solo le schede della finestra di chat sotto il mouse: quelle delle finestre agganciate insieme, o quella di una finestra staccata da sola."
L["WN52_3_TITLE"] = "Occhio della ricerca gruppo"
L["WN52_3_TEXT"] = "Aggancia alla minimappa per l'occhio della ricerca gruppo non è più nelle opzioni; resta nelle impostazioni dell'occhio in modalità modifica."
L["WN52_4_TITLE"] = "Occhio della ricerca gruppo"
L["WN52_4_TEXT"] = "Aggancia alla minimappa per l'occhio della ricerca gruppo è passato dalle opzioni al suo riquadro Ricerca gruppi in Finestre di ClassicUI Forever (modalità modifica), sotto Minimappa. Il riquadro resta finché l'occhio è fuori dal bordo, così puoi riattivarlo."
L["WN52_5_TITLE"] = "Suggerimento di Lampo di danno"
L["WN52_5_TEXT"] = "Il suggerimento di Lampo di danno dice che il rosso compare sulla barra della salute del riquadro del giocatore. Lampo di danno è disattivato in modo predefinito; attivalo nelle opzioni (/fcui), in Riquadri delle unità."
L["WN51_1_TITLE"] = "Maestria e Versatilità"
L["WN51_1_TEXT"] = "Le statistiche della finestra del personaggio mostrano Maestria e Versatilità, in Generale."
L["WN51_2_TITLE"] = "Finestra delle professioni"
L["WN51_2_TEXT"] = "La scelta dell'espansione ora è nel menu Filtro. La finestra si apre dove stanno le altre finestre del gioco, senza spazio dopo il libro degli incantesimi, e il suo bordo inferiore passa sotto i pulsanti Crea."
L["WN51_3_TITLE"] = "Opzioni di Una borsa"
L["WN51_3_TEXT"] = "Le opzioni sotto Una borsa cambiano solo le finestre delle borse dell'addon, quindi sono in grigio finché Finestre delle borse è disattivato. Per usarle, attivalo nelle opzioni (/fcui), in Borse."
L["WN51_4_TITLE"] = "Schede"
L["WN51_4_TEXT"] = "Nelle finestre delle professioni e dei talenti, la scheda scelta mostra tutta la sua faccia e le altre schede non mostrano più una fascia nera."
L["WN50_1_TITLE"] = "Colore con trama"
L["WN50_1_TEXT"] = "Colore con trama, che mantiene la trama della grafica nel colore del tema, ora colora finestre intere, non solo il loro metallo: la pietra di borse e schede, i bordi delle caselle di ricerca e di testo, e le frecce di pagina del libro degli incantesimi, dove una freccia usabile è più chiara di una esaurita. Disattivo in modo predefinito; attivalo nelle opzioni (/fcui), in Aspetto."
L["WN50_2_TITLE"] = "Temi sulle finestre del gioco"
L["WN50_2_TEXT"] = "I temi colorano anche la grafica del gioco rimasta nelle finestre che l'addon ridisegna: le schede della finestra sociale, le barre di scorrimento, le caselle di ricerca, i menu a tendina come quello dello stato, il riquadro del denaro, le intestazioni di colonna dell'elenco di gilda, la casella di chat delle comunità e la scheda dell'incursione."
L["WN50_3_TITLE"] = "Bronzo su retail"
L["WN50_3_TEXT"] = "Il tema Bronzo ora colora anche la grafica delle finestre del gioco, argentata su retail, come fanno gli altri temi."
L["WN50_4_TITLE"] = "Nascondi i pulsanti di aiuto"
L["WN50_4_TEXT"] = "Nasconde i pulsanti di aiuto del gioco, la i in alto a sinistra di finestre come la mappa, le professioni e il libro degli incantesimi, e i consigli del tutorial che aprono. Attivo in modo predefinito; disattivalo nelle opzioni (/fcui), in Altro."
L["WN50_5_TITLE"] = "Nascondi la scheda laterale Chi"
L["WN50_5_TEXT"] = "La ricerca gruppi può togliere la sua scheda laterale Chi, così Chi si apre solo dalla finestra sociale. Attivo per le nuove installazioni; se usavi già l'addon, attivalo nelle opzioni (/fcui), in Sociale."
L["WN50_6_TITLE"] = "Correzioni"
L["WN50_6_TEXT"] = "L'anello del ritratto del libro degli incantesimi prende il tema Bronzo invece di restare argentato, e una freccia di pagina che può di nuovo girare non tiene più il colore esaurito finché non clicchi altrove. Le targhette mostrano il teschio per le unità amiche di livello sconosciuto, come il riquadro del bersaglio. Il bordo interno delle schede Amici e Incursione della finestra sociale prende il colore del tema, ed è corretto un errore che il tema poteva causare in combattimento."
